/**
 * Batch History.
 *
 * The rows are the masterfile's own run log, so a batch generated by the CLI
 * shows up here too - the table is a view of what was really allocated, not a
 * list of what this browser session happened to do.
 */
import { useCallback, useEffect, useState } from 'react';
import { getHistory } from '../api/client.js';
import type { BatchRow } from '../api/types.js';

export function useBatchHistory() {
  const [rows, setRows] = useState<BatchRow[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(() => {
    setLoading(true);
    return getHistory()
      .then((r) => { setRows(r); setError(null); })
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { void refresh(); }, [refresh]);

  return { rows, error, loading, refresh };
}
